_DEFAULTS = {
    "debug": False,
    "page_size": 25,
    "features": [],
}


def _coerce_debug(value):
    return bool(value)


def _coerce_page_size(value):
    page_size = int(value)
    if page_size < 1 or page_size > 100:
        raise ValueError("page_size must be between 1 and 100")
    return page_size


def _coerce_features(value):
    if isinstance(value, str):
        return [value]
    if isinstance(value, list):
        return [str(feature) for feature in value]
    raise ValueError("features must be a string or list")


_COERCERS = {
    "debug": _coerce_debug,
    "page_size": _coerce_page_size,
    "features": _coerce_features,
}


def parse_config(raw: dict) -> dict:
    if not isinstance(raw, dict):
        raise TypeError("config must be a dictionary")

    parsed = {
        key: (list(default) if isinstance(default, list) else default)
        for key, default in _DEFAULTS.items()
    }
    for key, coerce in _COERCERS.items():
        if key in raw:
            parsed[key] = coerce(raw[key])
    return parsed

